from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode

def apply_rewrite_rules(rules, urls):
    results = []

    for url_str in urls:
        parsed_url = urlparse(url_str)
        matched = False

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            # 1. Check for match
            is_matched = False

            if match_type == "path_prefix":
                if parsed_url.path.startswith(match_value):
                    is_matched = True

            elif match_type == "host":
                host = parsed_url.hostname or ""
                if match_value.startswith("*."):
                    suffix = match_value[1:] # e.g., ".example.com"
                    # Must be a strict subdomain (e.g. sub.example.com, not example.com)
                    if host.endswith(suffix) and len(host) > len(suffix):
                        is_matched = True
                else:
                    if host == match_value:
                        is_matched = True

            elif match_type == "query_param":
                query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                if any(k == match_value for k, v in query_params):
                    is_matched = True

            # 2. If matched, apply action and stop evaluating further rules
            if is_matched:
                if action == "block":
                    results.append(None)
                    matched = True
                    break

                elif action == "strip_prefix":
                    # Remove action_value from the beginning of the path
                    path = parsed_url.path
                    if path.startswith(action_value):
                        path = path[len(action_value):]
                    if not path.startswith("/"):
                        path = "/" + path

                    parsed_url = parsed_url._replace(path=path)
                    results.append(urlunparse(parsed_url))
                    matched = True
                    break

                elif action == "redirect_host":
                    # Replace the host, preserving port if specified in original host
                    netloc = action_value
                    if parsed_url.port and ":" not in action_value:
                        netloc = f"{action_value}:{parsed_url.port}"

                    parsed_url = parsed_url._replace(netloc=netloc)
                    results.append(urlunparse(parsed_url))
                    matched = True
                    break

                elif action == "add_query_param":
                    # action_value should be like "key=value" or just parsed
                    query_params = parse_qsl(parsed_url.query, keep_blank_values=True)
                    if "=" in action_value:
                        k, v = action_value.split("=", 1)
                        query_params.append((k, v))

                    new_query = urlencode(query_params)
                    parsed_url = parsed_url._replace(query=new_query)
                    results.append(urlunparse(parsed_url))
                    matched = True
                    break

        # If no rules matched the URL, return it unchanged
        if not matched:
            results.append(url_str)

    return results
